<?php require dirname(__DIR__,2).'/layouts/admin_start.php'; $editing=!empty($role['id']); ?><section class="content-card form-card"><div class="section-heading"><div><h2><?= $editing?'Editar perfil':'Cadastrar perfil' ?></h2><p>O slug vazio será gerado automaticamente a partir do nome.</p></div><a class="button button-secondary" href="/admin/roles">Voltar</a></div><?php if($errors): ?><div class="alert alert-error"><ul><?php foreach($errors as $error): ?><li><?= htmlspecialchars($error,ENT_QUOTES,'UTF-8') ?></li><?php endforeach; ?></ul></div><?php endif; ?><form class="admin-form" method="post" action="<?= $editing?'/admin/roles/edit?id='.(int)$role['id']:'/admin/roles/create' ?>"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>"><div class="form-grid"><label><span>Nome *</span><input name="name" required value="<?= htmlspecialchars($role['name']??'',ENT_QUOTES,'UTF-8') ?>"></label><label><span>Slug</span><input name="slug" value="<?= htmlspecialchars($role['slug']??'',ENT_QUOTES,'UTF-8') ?>" placeholder="gerado-automaticamente"></label><label class="span-2"><span>Descrição</span><textarea name="description" rows="4"><?= htmlspecialchars($role['description']??'',ENT_QUOTES,'UTF-8') ?></textarea></label><label><span>Status</span><select name="status"><option value="active" <?= ($role['status']??'active')==='active'?'selected':'' ?>>Ativo</option><option value="inactive" <?= ($role['status']??'')==='inactive'?'selected':'' ?>>Inativo</option></select></label></div><div class="form-actions"><button class="button" type="submit">Salvar Perfil</button></div></form></section><?php require dirname(__DIR__,2).'/layouts/admin_end.php'; ?>
